import { auth } from "@/auth";
import { readQuotaSnapshot } from "@/lib/quota-usage";

export const dynamic = "force-dynamic";

export async function GET() {
  const headers = { "Cache-Control": "private, no-store" };
  const session = await auth();
  if (!session?.user?.id)
    return Response.json({ error: "Sign in first." }, { status: 401, headers });
  try {
    const snapshot = await readQuotaSnapshot(session.user.id);
    return Response.json(
      snapshot.mode === "legacy"
        ? {
            used: snapshot.used,
            limit: snapshot.limit,
            notices: snapshot.notices,
            accessVersion: snapshot.accessVersion,
          }
        : snapshot,
      { headers },
    );
  } catch {
    return Response.json(
      { error: "Quota unavailable." },
      { status: 503, headers },
    );
  }
}
